using System;
using UnityEngine;
using HarborValeGreybox.Workshop;
namespace HarborValeGreybox.Racing {
public sealed partial class RaceProgressStore {
 public bool HasEngine(string carId)=>EngineInventoryLedger.HasEngine(Profile.fleet,carId);
 public string ActiveEngineModelId=>Profile.fleet.selectedId==FleetLedger.Loaner?"car_finch":EngineInventoryLedger.Find(Profile.fleet,FleetLedger.Find(Profile.fleet,Profile.fleet.selectedId).engineId).modelId;
 public int EngineFitFee(string engineId,string carId)=>EngineInventoryLedger.FitFee(Profile.fleet,engineId,carId);
 public int EngineTransferFee(string donorCarId,string receiverCarId){var donor=FleetLedger.Find(Profile.fleet,donorCarId);return EngineInventoryLedger.FitFee(Profile.fleet,donor.engineId,receiverCarId,true,donorCarId);}
 public void PullEngine(string request,string carId)=>MoveEngine(request,"engine_pull",carId,null,null,0);
 public void FitEngine(string request,string engineId,string carId,int quotedFee)=>MoveEngine(request,"engine_fit",null,carId,engineId,quotedFee);
 public void TransferEngine(string request,string donorCarId,string receiverCarId,int quotedFee)=>MoveEngine(request,"engine_transfer",donorCarId,receiverCarId,null,quotedFee);
 void MoveEngine(string request,string kind,string donorId,string receiverId,string engineId,int quotedFee){if(!Guid.TryParse(request,out _))throw new ArgumentException("Invalid engine transaction identity");using(Lock()){var latest=Load();Profile=latest;foreach(var old in latest.spending)if(old.transactionId==request){var prior=JsonUtility.FromJson<EngineMove>(old.fleetJson);if(old.kind!=kind||old.credits!=quotedFee||prior==null||(prior.donorId??"")!=(donorId??"")||(prior.receiverId??"")!=(receiverId??"")||engineId!=null&&prior.engineId!=engineId)throw new InvalidOperationException("Engine request conflicts with committed transaction");return;}EngineInventoryLedger.Ensure(latest.fleet);if(donorId!=null){var donor=FleetLedger.Find(latest.fleet,donorId);if(!EngineInventoryLedger.HasEngine(latest.fleet,donor.id))throw new InvalidOperationException("Donor car has no engine");engineId=donor.engineId;}int fee=kind=="engine_pull"?0:EngineInventoryLedger.FitFee(latest.fleet,engineId,receiverId,kind=="engine_transfer",donorId);TrafficLedger.CanSpend(latest,fee);if(quotedFee!=fee)throw new InvalidOperationException("Engine labor quote changed");if(latest.availableCredits<fee)throw new InvalidOperationException("Not enough credits for the mounting/ECU labor");var move=new EngineMove{engineId=engineId,donorId=donorId,receiverId=receiverId,fee=fee};var receipt=new TuneReceipt{transactionId=request,prototypeCarId=latest.prototypeCarId,kind=kind,pathId="inventory_v9",partId=engineId,configId=receiverId??donorId,stage=0,credits=fee,paidUtc=DateTime.UtcNow.ToString("o"),fleetJson=JsonUtility.ToJson(move)};var candidate=JsonUtility.FromJson<RaceProgress>(JsonUtility.ToJson(latest));candidate.spending.Add(receipt);candidate.availableCredits=checked(candidate.availableCredits-fee);Validate(candidate,true);Write(candidate);Profile=candidate;}}
}
}
